"mt_oIzycTBeE4":{"intro":"The equals sign means balance! ⚖️","items":[{"t":"tf","q":"6 = 6 is true.","a":true,"why":"Both sides are the same."},{"t":"tf","q":"4 + 1 = 5 + 2 is true.","a":false,"why":"4 + 1 is 5 but 5 + 2 is 7. They don't balance."},{"t":"pick","q":"What does = mean?","opts":["is the same as","the answer comes next","add them up"],"why":"= tells us both sides have the same value."},{"t":"sort","q":"True or false?","bins":["True","False"],"items":[["7 = 3 + 4",0],["2 + 8 = 5 + 5",0],["9 = 9 + 1",1],["3 + 3 = 7",1],["10 - 2 = 8",0]],"why":"An equation is true when both sides match."},{"t":"type","q":"5 + 3 = ? + 6. Type the missing number.","a":["2","two"],"why":"5 + 3 = 8, and 2 + 6 = 8."}]},
